(function (global) {
    'use strict';

    function escapeHtml(str) {
        return String(str ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function configureMarked() {
        if (!global.marked) return;

        const renderer = new global.marked.Renderer();
        // 不允許原始 HTML：將區塊與行內 HTML 轉成跳脫後的原始字串輸出
        renderer.html = ({ text }) => escapeHtml(text);

        global.marked.use({ renderer });
    }

    function renderSafeMarkdown(markdownText) {
        const raw = markdownText ?? '';
        if (!raw.trim()) return '';

        if (global.marked) {
            const html = global.marked.parse(raw);
            return global.DOMPurify ? global.DOMPurify.sanitize(html) : html;
        }

        return escapeHtml(raw).replace(/\n/g, '<br>');
    }

    configureMarked();

    global.escapeMarkdownHtml = escapeHtml;
    global.renderSafeMarkdown = renderSafeMarkdown;
})(typeof window !== 'undefined' ? window : globalThis);